import { SpotLight } from '@orillusion/core';

// The wall switch of the laundromat: clicking it (or pressing L) turns the
// ceiling fluorescents off and on. With them off the room falls back on the
// neon sign and the street lamp coming through the glass.
export default class FluorescentSwitch extends Script {
    intensity = 0.85;   // fixture brightness while on
    fade = 3;           // how quickly they come up and go down
    count = 6;          // how many ceiling fixtures the switch controls

    start() {
        this.on = true;
        this.spot = [];
        this.tubeNames = [];
        for (let i = 1; i <= this.count; i++) {
            const light = this.find('Fluorescent Light ' + i);
            const comp = light && light.getComponent ? light.getComponent(SpotLight) : null;
            if (comp) this.spot.push(comp);
            this.tubeNames.push('Fluorescent Tube ' + i);
        }
        this.glow(this.on);
    }

    glow(on) {
        for (const name of this.tubeNames) {
            const obj = this.find(name);
            if (obj) this.setEmissive(on ? '#eaf6ff' : '#151b21', on ? 2.5 : 0, obj);
        }
    }

    toggle() {
        this.on = !this.on;
        this.glow(this.on);
        this.playSound('switch', { volume: 0.5, at: this.object3D });
        this.log('fluorescent lights', this.on ? 'on' : 'off');
    }

    update(dt) {
        const target = this.on ? this.intensity : 0;
        for (const light of this.spot) {
            if (typeof light.intensity !== 'number') continue;
            light.intensity += (target - light.intensity) * Math.min(1, dt * this.fade);
        }
    }

    onPointerDown() { this.toggle(); }
    onKeyDown(key) { if (key === 'l') this.toggle(); }
}

