// World space triplanar surface (@morglay triplanar): the albedo, normal
// and ARM (occlusion, roughness, metallic) textures are projected along x, y
// and z and blended by the surface normal, so they keep their real size on
// every mesh. tile is the size of one texture tile in meters. Only the
// projections a surface faces are read: a floor or a wall reads each texture
// once. maps says which textures there are (1: normal, 2: ARM); roughness and
// metallic multiply the ARM map's.
// @property albedo texture white
// @property normalTex texture normal
// @property armTex texture data
// @property tile float 2 0.05 50
// @property sharpness float 4 1 16
// @property normalStrength float 1 0 2
// @property maps float 0 0 3

struct Triplanar {
    color: vec4f,
    arm: vec3f,
    // The normal maps' slope, in world space.
    bump: vec3f,
};

fn triplanarSample(p: vec3f, n: vec3f) -> Triplanar {
    let s = 1.0 / max(materialUniform.tile, 0.001);
    var w = pow(abs(n), vec3f(materialUniform.sharpness));
    w = w / max(w.x + w.y + w.z, 0.0001);
    // Leave out the projections that barely count, then weigh the rest to one.
    w = select(vec3f(0.0), w, w > vec3f(0.02));
    w = w / max(w.x + w.y + w.z, 0.0001);
    // Gradients while every pixel runs here: the projections below read
    // only where they weigh (textureSampleGrad needs no uniform flow).
    let dx = dpdx(p) * s;
    let dy = dpdy(p) * s;
    let flags = u32(materialUniform.maps + 0.5);
    let useNormal = (flags & 1u) != 0u;
    let useArm = (flags & 2u) != 0u;
    var out: Triplanar;
    out.color = vec4f(0.0);
    out.arm = vec3f(0.0);
    out.bump = vec3f(0.0);
    // Along x: u east (+z), up the image +y.
    if (w.x > 0.0) {
        let uv = vec2f(p.z, -p.y) * s;
        let gx = vec2f(dx.z, -dx.y);
        let gy = vec2f(dy.z, -dy.y);
        out.color += textureSampleGrad(albedo, albedoSampler, uv, gx, gy) * w.x;
        out.arm += select(vec3f(1.0), textureSampleGrad(armTex, armTexSampler, uv, gx, gy).rgb, useArm) * w.x;
        if (useNormal) {
            let t = textureSampleGrad(normalTex, normalTexSampler, uv, gx, gy).xy * 2.0 - 1.0;
            out.bump += (t.x * vec3f(0.0, 0.0, 1.0) + t.y * vec3f(0.0, 1.0, 0.0)) * w.x;
        }
    }
    // Along y: u +x, up the image -z.
    if (w.y > 0.0) {
        let uv = vec2f(p.x, p.z) * s;
        let gx = vec2f(dx.x, dx.z);
        let gy = vec2f(dy.x, dy.z);
        out.color += textureSampleGrad(albedo, albedoSampler, uv, gx, gy) * w.y;
        out.arm += select(vec3f(1.0), textureSampleGrad(armTex, armTexSampler, uv, gx, gy).rgb, useArm) * w.y;
        if (useNormal) {
            let t = textureSampleGrad(normalTex, normalTexSampler, uv, gx, gy).xy * 2.0 - 1.0;
            out.bump += (t.x * vec3f(1.0, 0.0, 0.0) + t.y * vec3f(0.0, 0.0, -1.0)) * w.y;
        }
    }
    // Along z: u +x, up the image +y.
    if (w.z > 0.0) {
        let uv = vec2f(p.x, -p.y) * s;
        let gx = vec2f(dx.x, -dx.y);
        let gy = vec2f(dy.x, -dy.y);
        out.color += textureSampleGrad(albedo, albedoSampler, uv, gx, gy) * w.z;
        out.arm += select(vec3f(1.0), textureSampleGrad(armTex, armTexSampler, uv, gx, gy).rgb, useArm) * w.z;
        if (useNormal) {
            let t = textureSampleGrad(normalTex, normalTexSampler, uv, gx, gy).xy * 2.0 - 1.0;
            out.bump += (t.x * vec3f(1.0, 0.0, 0.0) + t.y * vec3f(0.0, 1.0, 0.0)) * w.z;
        }
    }
    return out;
}

fn frag() {
    let n = normalize(ORI_VertexVarying.vWorldNormal);
    let p = ORI_VertexVarying.vWorldPos.xyz;
    let t = triplanarSample(p, n);
    let c = t.color * materialUniform.baseColor;
    ORI_ShadingInput.BaseColor = vec4f(c.rgb, materialUniform.baseColor.a);
    ORI_ShadingInput.Roughness = clamp(t.arm.g * materialUniform.roughness, 0.02, 1.0);
    ORI_ShadingInput.Metallic = t.arm.b * materialUniform.metallic;
    ORI_ShadingInput.Specular = 1.0;
    ORI_ShadingInput.AmbientOcclusion = t.arm.r;
    ORI_ShadingInput.EmissiveColor = vec4f(materialUniform.emissiveColor.rgb, 1.0);
    ORI_ShadingInput.Normal = normalize(n + t.bump * materialUniform.normalStrength);
    useShadow();
    BxDFShading();
}

// Water for a flat surface (a plane). mirrorColor(offset) is the scene a
// Mirror component on the object reflects, moved by offset (screen units);
// its alpha is 0 without one, and the sky is reflected instead.
// @property deepColor color #0b2a36
// @property shallowColor color #1f5e66
// @property waveScale float 1 0.05 5
// @property waveSpeed float 1 0 5
// @property waveHeight float 0.15 0 1
// @property distortion float 0.03 0 0.2
// @property reflectivity float 1 0 1

// Slopes of three waves across the surface.
fn waveSlope(p: vec2f, t: f32) -> vec2f {
    let k = materialUniform.waveScale;
    var s = vec2f(0.8, 0.6) * cos(dot(p, vec2f(0.8, 0.6)) * 1.1 * k + t * 1.2);
    s += vec2f(-0.5, 0.87) * cos(dot(p, vec2f(-0.5, 0.87)) * 2.3 * k - t * 1.7) * 0.5;
    s += vec2f(0.28, -0.96) * cos(dot(p, vec2f(0.28, -0.96)) * 4.9 * k + t * 2.3) * 0.25;
    return s * materialUniform.waveHeight;
}

fn frag() {
    let p = ORI_VertexVarying.vWorldPos.xyz;
    let slope = waveSlope(p.xz, getTime() * materialUniform.waveSpeed);
    let n = normalize(vec3f(-slope.x, 1.0, -slope.y));
    let v = normalize(globalUniform.CameraPos.xyz - p);
    let nv = max(dot(n, v), 0.0);
    let fresnel = 0.02 + 0.98 * pow(1.0 - nv, 5.0);
    let r = reflect(-v, n);

    // The mirrored scene where there is one, else the sky.
    let mirror = mirrorColor(n.xz * materialUniform.distortion);
    let sky = textureSampleLevel(prefilterMap, prefilterMapSampler, r, 0.0).rgb * globalUniform.skyExposure;
    let reflection = mix(sky, mirror.rgb, mirror.a) * materialUniform.reflectivity;
    let sun = lightBuffer[0];
    let glint = pow(max(dot(r, -normalize(sun.direction)), 0.0), 600.0) * sun.lightColor.rgb * sun.intensity * 8.0;

    ORI_ShadingInput.BaseColor = vec4f(mix(materialUniform.deepColor.rgb, materialUniform.shallowColor.rgb, sqrt(nv)) * (1.0 - fresnel), 1.0);
    // Rough, so the lighting adds no reflection of its own over this one.
    ORI_ShadingInput.Roughness = 1.0;
    ORI_ShadingInput.Metallic = 0.0;
    ORI_ShadingInput.Specular = 0.0;
    ORI_ShadingInput.AmbientOcclusion = 1.0;
    ORI_ShadingInput.Normal = n;
    useShadow();
    // Emission is read as gamma-encoded color: encode the linear light.
    let light = reflection * fresnel + glint * directShadowVisibility[0];
    ORI_ShadingInput.EmissiveColor = vec4f(pow(max(light, vec3f(0.0)), vec3f(1.0 / 2.4)), 1.0);
    BxDFShading();
}

// Post shader: return the new color for screen position uv (0..1).
// sceneColor(uv) reads the image produced by the passes before this one.
// @property strength float 0.6 0 2
// @property radius float 0.75 0.1 1.5
// @property tint color #000000

fn post(uv: vec2f) -> vec4f {
    let c = sceneColor(uv);
    let d = distance(uv, vec2f(0.5));
    let v = smoothstep(materialUniform.radius, materialUniform.radius - 0.45, d);
    let k = mix(1.0, v, materialUniform.strength);
    return vec4f(mix(materialUniform.tint.rgb, c.rgb, clamp(k, 0.0, 1.0)), c.a);
}

// Post shader: lift, gamma and gain, then saturation. It works on the HDR
// image before tone mapping: lift raises the darks, gamma bends the mid
// tones, gain scales everything. x, y, z are red, green and blue; w applies
// to all three (lift and gain add / multiply it, gamma multiplies it).
// @property lift vec4 0 0 0 0
// @property gamma vec4 1 1 1 1
// @property gain vec4 1 1 1 1
// @property saturation float 1 0 2

fn post(uv: vec2f) -> vec4f {
    let c = sceneColor(uv);
    let lift = materialUniform.lift.xyz + vec3f(materialUniform.lift.w);
    let gamma = max(materialUniform.gamma.xyz * materialUniform.gamma.w, vec3f(0.01));
    let gain = materialUniform.gain.xyz * materialUniform.gain.w;
    var x = max(c.rgb, vec3f(0.0));
    x = x + lift * max(vec3f(1.0) - x, vec3f(0.0));
    x = max(x * gain, vec3f(0.0));
    x = pow(x, vec3f(1.0) / gamma);
    let luma = dot(x, vec3f(0.2126, 0.7152, 0.0722));
    x = mix(vec3f(luma), x, materialUniform.saturation);
    return vec4f(max(x, vec3f(0.0)), c.a);
}

// The rain volume: ONE box, and inside it the drops live at real positions in
// space - no cards, no layers of rain. For every pixel the shader walks the
// eye ray through the volume in steps of one cell. Each cell holds one falling
// drop on a line of its own; where the ray passes within that drop's width the
// exact chord through the drop is added, so drops stay thin and get their right
// size from their distance. Drops fall in world Y, stop at the ground, lean
// with the wind, and fade out close to the camera and at the volume's edges.
//
// Dry box: the drops are kept out of one box in space, so no rain falls under
// the awning (the eaves) while the same drop lines carry on above it and just
// past its edge - the rain reads as running off the rim. Soft edges: dryFade.
//
// The box has to sit inside the open air of the street (a little clear of the
// walls, the shop front and the ground, and high enough that its top is above
// the walls): then every face the eye ray leaves through stays in the open and
// the rain is drawn in every direction, walls included.
//
// Cost: this runs on every pixel of the volume, so the per cell tests stay
// cheap. Before anything else each cell is tested against the ray through its
// middle with the largest offset a drop can have from that middle (0.43 cell on
// each axis) added to the widest the drop can be: nine cells out of ten drop
// out there, without a single hash. What is left is hashed with an integer
// hash (a handful of integer ops, no transcendental functions) and the
// distance test compares squared distances, so the square root only runs for
// the few cells a pixel actually hits. The four cells of a step are written
// out instead of looped, so no integer division lands in the inner loop.
//
// @property boxMin vec4 -7.6 0.3 7.4 0
// @property boxMax vec4 7.6 12.0 15.6 0
// @property cell float 0.72 0.2 3
// @property drop_width float 0.02 0.004 0.08
// @property fill float 0.85 0.05 1
// @property density float 8.5 0.2 30
// @property dash_len float 0.6 0.05 3
// @property fall_speed float 9.5 1 25
// @property slant float 0.08 -0.5 0.5
// @property bottom float 0.0 -5 10
// @property intensity float 1.5 0 4
// @property near_fade float 3.0 0.2 20
// @property tint color #e8f0f8
// @property lampTint color #ffbe73
// @property lampGain float 0.9 0 3
// @property lampPos vec4 -7.1 3.6 9.6 7
// @property dryMin vec4 -3.3 0.3 6.8 0
// @property dryMax vec4 3.3 3.42 8.55 0
// @property dryFade float 0.3 0 2

// Integer hash: three multiply-xor rounds on the cell id, about a third of the
// cost of the floating point hash it replaces. The top round of bits is dropped
// before the conversion so the 24 bit mantissa is filled with usable bits.
fn hashCell(c: vec2i, seed: u32) -> f32 {
    var h: u32 = u32(c.x) * 1597334673u + u32(c.y) * 3812015801u + seed;
    h = (h ^ (h >> 15u)) * 2246822519u;
    h = (h ^ (h >> 13u)) * 3266489917u;
    h = h ^ (h >> 16u);
    return f32(h >> 8u) * (1.0 / 16777216.0);
}

struct Ray {
    ox: f32,
    oz: f32,
    dx: f32,
    dz: f32,
    camY: f32,
    dirY: f32,
    denom: f32,
    shear2: f32
};

// What one drop of this cell adds to this pixel.
fn dropContribution(cid: vec2i, r: Ray, ta: f32, tb: f32) -> vec4f {
    let cell = materialUniform.cell;
    let bmin = materialUniform.boxMin.xyz;
    let bmax = materialUniform.boxMax.xyz;

    if (r.denom < 1.0e-4) {
        return vec4f(0.0);
    }

    // Cheap out first: the drop's line sits within 0.43 * cell of the middle of
    // its cell on each axis, so if the ray misses that middle by more than the
    // largest that offset can reach the drop cannot be hit either. Most cells
    // of the block are gone here, before any hash is spent on them.
    let cx = (f32(cid.x) + 0.5) * cell;
    let cz = (f32(cid.y) + 0.5) * cell;
    let tsc = ((cx - r.ox) * r.dx + (cz - r.oz) * r.dz) / r.denom;
    let ddxc = (r.ox + r.dx * tsc) - cx;
    let ddzc = (r.oz + r.dz * tsc) - cz;
    let rho2c = (ddxc * ddxc + ddzc * ddzc) * r.shear2;
    let reach = 0.608 * cell + 1.3 * materialUniform.drop_width;
    if (rho2c > reach * reach) {
        return vec4f(0.0);
    }

    let h1 = hashCell(cid, 0u);
    if (h1 >= materialUniform.fill) {
        return vec4f(0.0);
    }
    let h2 = hashCell(cid, 0x9E3779B9u);
    let h3 = hashCell(cid, 0x85EBCA6Bu);

    // the drop's line sits somewhere jittered inside its cell
    let lx = (f32(cid.x) + 0.5 + (h2 - 0.5) * 0.86) * cell;
    let lz = (f32(cid.y) + 0.5 + (h3 - 0.5) * 0.86) * cell;

    // where the eye ray comes closest to that line
    let ts = ((lx - r.ox) * r.dx + (lz - r.oz) * r.dz) / r.denom;
    if (ts < ta || ts > tb) {
        return vec4f(0.0);
    }

    let ddx = (r.ox + r.dx * ts) - lx;
    let ddz = (r.oz + r.dz * ts) - lz;
    // squared distance, so the square root only runs where a drop is hit
    let rho2 = (ddx * ddx + ddz * ddz) * r.shear2;
    let w = materialUniform.drop_width * (0.7 + 0.6 * h3);
    if (rho2 >= w * w) {
        return vec4f(0.0);
    }
    let rho = sqrt(rho2);

    let yAt = r.camY + r.dirY * ts;
    let dash = materialUniform.dash_len * (0.7 + 0.6 * h2);
    let yv = yAt + getTime() * materialUniform.fall_speed * (0.85 + 0.3 * h3) + h1 * 11.0;
    let f = fract(yv / dash);
    var prof = smoothstep(0.0, 0.16, f) * (1.0 - smoothstep(0.42, 0.62, f));
    prof *= smoothstep(materialUniform.bottom - 0.25, materialUniform.bottom + 0.7, yAt);
    prof *= 1.0 - smoothstep(bmax.y - 1.6, bmax.y, yAt);
    let px = lx - materialUniform.slant * yAt;
    let pz = r.oz + r.dz * ts;
    // keep the rain a little clear of the walls, the shop front and the far wall
    prof *= smoothstep(bmin.x, bmin.x + 0.5, px) * (1.0 - smoothstep(bmax.x - 0.5, bmax.x, px));
    prof *= 1.0 - smoothstep(bmax.z - 0.5, bmax.z, pz);

    // the eaves: nothing falls inside the dry box (its footprint is the awning),
    // so under the canopy it stays dry while the same drop lines carry on above
    // it and just past its rim.
    let dmn = materialUniform.dryMin.xyz;
    let dmx = materialUniform.dryMax.xyz;
    let dr = materialUniform.dryFade + 1.0e-3;
    let inx = smoothstep(dmn.x - dr, dmn.x, px) * (1.0 - smoothstep(dmx.x, dmx.x + dr, px));
    let iny = smoothstep(dmn.y, dmn.y + 0.1, yAt) * (1.0 - smoothstep(dmx.y - dr, dmx.y, yAt));
    let inz = smoothstep(dmn.z - dr, dmn.z, pz) * (1.0 - smoothstep(dmx.z, dmx.z + dr, pz));
    prof *= 1.0 - inx * iny * inz;
    if (prof <= 0.0) {
        return vec4f(0.0);
    }

    // how much rain this drop puts in the way, along the ray
    let chord = 2.0 * sqrt(max(w * w - rho2, 0.0));
    var a = 1.0 - exp(-materialUniform.density * chord * prof);
    a *= smoothstep(0.35, materialUniform.near_fade, ts);
    a *= materialUniform.intensity * (0.5 + 0.7 * h2);
    a = clamp(a, 0.0, 1.0);

    // the drop is lit a little by the street lamp it falls past
    let dl = vec3f(px, yAt, pz) - materialUniform.lampPos.xyz;
    let glow = clamp(exp(-dot(dl, dl) / (materialUniform.lampPos.w * materialUniform.lampPos.w)), 0.0, 1.0);
    let c = mix(materialUniform.tint.rgb, materialUniform.lampTint.rgb, glow)
        * (0.7 + 0.6 * h3) * (1.0 + materialUniform.lampGain * glow);

    return vec4f(c * a, a);
}

fn frag() {
    let cam = globalUniform.CameraPos.xyz;
    let wp = ORI_VertexVarying.vWorldPos.xyz;
    let dv = wp - cam;
    let dist = length(dv);
    if (dist < 1.0e-4) {
        discard;
    }
    let dir = dv / dist;

    let bmin = materialUniform.boxMin.xyz;
    let bmax = materialUniform.boxMax.xyz;
    let sd = select(dir, vec3f(1.0e-6, 1.0e-6, 1.0e-6), abs(dir) < vec3f(1.0e-6));
    let ta3 = (bmin - cam) / sd;
    let tb3 = (bmax - cam) / sd;
    let tnear = max(max(min(ta3.x, tb3.x), min(ta3.y, tb3.y)), min(ta3.z, tb3.z));
    let tfar = min(min(max(ta3.x, tb3.x), max(ta3.y, tb3.y)), max(ta3.z, tb3.z));
    if (tfar <= max(tnear, 0.0)) {
        discard;
    }

    // from outside, only the surface the ray enters at draws, so the volume is
    // walked exactly once per pixel
    let camInside = all(cam >= bmin) && all(cam <= bmax);
    if (!camInside && dist > tnear + 0.4) {
        discard;
    }

    let t0 = max(tnear, 0.0);
    let t1 = min(tfar, t0 + 40.0);

    let slant = materialUniform.slant;
    var r: Ray;
    r.ox = cam.x + slant * cam.y;
    r.oz = cam.z;
    r.dx = dir.x + slant * dir.y;
    r.dz = dir.z;
    r.denom = r.dx * r.dx + r.dz * r.dz;
    r.shear2 = 1.0 / (1.0 + slant * slant);
    r.camY = cam.y;
    r.dirY = dir.y;

    let step = materialUniform.cell;
    var acc = 0.0;
    var col = vec3f(0.0);

    for (var i: i32 = 0; i < 34; i = i + 1) {
        let ta = t0 + f32(i) * step;
        if (ta >= t1 || acc > 0.9) {
            break;
        }
        let tb = min(ta + step, t1);
        let p = cam + dir * (ta + step * 0.5);
        let base = vec2i(floor(vec2f(p.x, p.z) / step - vec2f(0.5, 0.5)));
        // the four cells of the block, written out: (0,0) (1,0) (0,1) (1,1)
        let c00 = dropContribution(base, r, ta, tb);
        if (c00.a > 0.0) {
            col = col + c00.rgb * (1.0 - acc);
            acc = acc + c00.a * (1.0 - acc);
        }
        let c10 = dropContribution(base + vec2i(1, 0), r, ta, tb);
        if (c10.a > 0.0) {
            col = col + c10.rgb * (1.0 - acc);
            acc = acc + c10.a * (1.0 - acc);
        }
        let c01 = dropContribution(base + vec2i(0, 1), r, ta, tb);
        if (c01.a > 0.0) {
            col = col + c01.rgb * (1.0 - acc);
            acc = acc + c01.a * (1.0 - acc);
        }
        let c11 = dropContribution(base + vec2i(1, 1), r, ta, tb);
        if (c11.a > 0.0) {
            col = col + c11.rgb * (1.0 - acc);
            acc = acc + c11.a * (1.0 - acc);
        }
    }

    if (acc < 0.004) {
        discard;
    }
    ORI_ShadingInput.BaseColor = vec4f(col / max(acc, 1.0e-4), acc);
    UnLit();
}

// Post shader: return the new color for screen position uv (0..1).
// sceneColor(uv) reads the image produced by the passes before this one.
//
// Vignette and colour grade in ONE pass: the vignette darkens the frame edges,
// then lift raises the darks, gamma bends the mid tones, gain scales
// everything and saturation pulls the colours in or out. Both halves are per
// pixel, so running them in one shader is the same image as the two separate
// passes were - it just costs one full screen pass and one render target
// instead of two.
//
// @property strength float 0.6 0 2
// @property radius float 0.75 0.1 1.5
// @property tint color #000000
// @property lift vec4 0 0 0 0
// @property gamma vec4 1 1 1 1
// @property gain vec4 1 1 1 1
// @property saturation float 1 0 2

fn post(uv: vec2f) -> vec4f {
    let c = sceneColor(uv);

    // vignette
    let d = distance(uv, vec2f(0.5));
    let v = smoothstep(materialUniform.radius, materialUniform.radius - 0.45, d);
    let k = mix(1.0, v, materialUniform.strength);
    var x = mix(materialUniform.tint.rgb, c.rgb, clamp(k, 0.0, 1.0));

    // lift, gamma, gain and saturation
    let lift = materialUniform.lift.xyz + vec3f(materialUniform.lift.w);
    let gamma = max(materialUniform.gamma.xyz * materialUniform.gamma.w, vec3f(0.01));
    let gain = materialUniform.gain.xyz * materialUniform.gain.w;
    x = max(x, vec3f(0.0));
    x = x + lift * max(vec3f(1.0) - x, vec3f(0.0));
    x = max(x * gain, vec3f(0.0));
    x = pow(x, vec3f(1.0) / gamma);
    let luma = dot(x, vec3f(0.2126, 0.7152, 0.0722));
    x = mix(vec3f(luma), x, materialUniform.saturation);

    return vec4f(max(x, vec3f(0.0)), c.a);
}
